with nq as (
  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'long_answer', 'a) One of the prominent figures in the cultural history of Bhutan is Thangtong Gyalpo (1385-1464), remembered for his many iron chain suspension bridges across the country and as a composer of occupational songs. Discuss some of his greatest contributions that shaped the social and cultural life of the Bhutanese people. (10 marks)', 'a) Thangtong Gyalpo (1385-1464), the great Tibetan yogi and engineer known as Chakzampa (''iron bridge builder''), visited Bhutan in the 15th century. Contributions: (1) Iron chain suspension bridges - he mined and forged iron in Bhutan and built many iron chain bridges, such as the one at Tamchog across the Paro Chhu, which made travel, trade, pilgrimage and communication across rivers safer and connected communities; (2) iron-working skills he introduced spread among local smiths; (3) religious foundations - he built temples such as Tamchog Lhakhang and Dumtse Lhakhang in Paro, and his Chakzampa lineage continues at Tamchog; (4) culture and arts - he is credited with composing occupational and work songs and is regarded as a founder of the Ache Lhamo performing tradition, enriching folk culture; (5) a model of service - his bridges were acts of compassion for travellers, inspiring the Bhutanese ideal of building for the common good.', null, '[{"point": "Thangtong Gyalpo (Chakzampa): iron chain suspension bridges improving travel, trade and pilgrimage (e.g. Tamchog near Paro, bridges in Paro/ Haa/ Trashigang areas), iron working technology; founded temples (Tamchog Lhakhang, Dumtse Lhakhang in Paro)", "marks": 5}, {"point": "Cultural: occupational/ work songs and performing arts (Ache Lhamo tradition), spiritual teachings and lineage (Chakzampa lineage at Tamchog), medicine/ blessings, social service ethic; legacy in folklore", "marks": 5}]'::jsonb, (select id from public.subjects where slug = 'bhutan-institutions-development'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'bhutan-institutions-development') and t.slug = 'history-great-figures'), (select id from public.exam_papers where code = 'me-general-3'), 'standard', 10,
    1080, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": [], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper III (General): BCSE 2022, batch 2", "source": {"title": "BCSE 2022 Main Examination, General category, Paper III", "year": 2022, "url": "https://rcsc.gov.bt/bcse-past-question-papers/"}}'::jsonb, 'me-general-3-2022b2-a1', 1, null, null, null, null)
  returning id
)
