  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'long_answer', 'b) Desi Tenzin Rabgye (reigned 1680-1694) is reckoned as one of the great figures in Bhutanese history. He was perhaps the only effective ruler after the great Zhabdrung who combined in his person complete spiritual and temporal authority. Discuss some of his significant socio-religious and political achievements as Druk Desi in fulfilling Zhabdrung''s vision of a unified sovereign nation. (10 marks)', 'b) Desi Tenzin Rabgye, the fourth Druk Desi (1680-1694), was the son of Tshewang Tenzin and was trained by Zhabdrung himself. Socio-religious achievements: he built Tango Monastery (1688) and the first temple at Paro Taktsang (1692) at the cave of Guru Rinpoche; he strengthened the monastic body, its education and rituals, and promoted religious ceremonies and festivals that continue today. Political achievements: he extended and consolidated central Drukpa authority over eastern Bhutan, strengthening the unity of the country; he improved administration and the appointment of officials, upheld the laws, and maintained peace and stability during the period when Zhabdrung''s death was kept secret (Zhabdrung said to be in retreat); and, combining spiritual and temporal authority, he governed according to Zhabdrung''s vision of a unified, sovereign state.', null, '[{"point": "Religious: built Tango Monastery (1688) and the first Taktsang Lhakhang (1692) at the Guru''s cave, strengthened monastic body, rituals and festivals, promoted Drukpa teachings", "marks": 4}, {"point": "Political: extended central authority to eastern Bhutan and consolidated territory, strengthened administration and laws, appointed officials, maintained stability and unity during the period of Zhabdrung''s ''retreat'', combined spiritual and temporal authority as Zhabdrung intended", "marks": 6}]'::jsonb, (select id from public.subjects where slug = 'bhutan-institutions-development'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'bhutan-institutions-development') and t.slug = 'history-great-figures'), (select id from public.exam_papers where code = 'me-general-3'), 'standard', 10,
