with nq as (
  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'long_answer', 'a) Despite its importance in making Bhutan''s democracy ever vibrant and sustaining, our media organisations face many constraints. Discuss some of the major constraints of media organisations and what, in your opinion, needs to be done to overcome them. (10 marks)', 'a) Constraints: (1) a very small market with limited advertising revenue, so private newspapers and broadcasters struggle financially and several have closed or reduced staff; (2) heavy dependence on government advertising, which can encourage self-censorship; (3) shortage of experienced journalists and high turnover because of low pay; (4) difficulty accessing information from public agencies; (5) limited capacity and resources for investigative journalism; (6) competition from social media, where unverified news and misinformation spread fast.
What needs to be done: a fair and transparent advertising policy and support (e.g. a media development fund) without political strings; a Right to Information Act; training, scholarships and better pay for journalists; strong professional and ethical standards through the Media Council; protecting media independence; helping media diversify revenue through digital platforms; and promoting media literacy among citizens.', null, '[{"point": "Constraints: small market and low advertising revenue, dependence on government ads, financial unsustainability and closures, shortage of skilled/ experienced journalists and high turnover, limited access to information, self-censorship and fear, competition from social media and misinformation, limited investigative capacity", "marks": 5}, {"point": "Solutions: fair advertising policy and support fund, Right to Information law, training and capacity building, professional standards, media independence, diversify revenue (digital), media literacy", "marks": 5}]'::jsonb, (select id from public.subjects where slug = 'bhutan-institutions-development'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'bhutan-institutions-development') and t.slug = 'media-and-culture'), (select id from public.exam_papers where code = 'me-general-3'), 'standard', 10,
    1080, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": [], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper III (General): BCSE 2022, batch 2", "source": {"title": "BCSE 2022 Main Examination, General category, Paper III", "year": 2022, "url": "https://rcsc.gov.bt/bcse-past-question-papers/"}}'::jsonb, 'me-general-3-2022b2-a3', 1, null, null, null, null)
  returning id
)
