with nq as (
  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'long_answer', 'b) Bhutan is the stage for some of the most vibrant and unique religious tshechus (festivals) in the world. These festivals play an integral part in forging Bhutan''s identity on the world map as a tourist destination. Discuss the significance of tshechus with special reference to their religious, historical and social importance to the Bhutanese people. (10 marks)', 'b) Religious significance: tshechus are held in honour of Guru Rinpoche, usually on the tenth day of the month; the sacred mask dances (cham) depict teachings and events from Buddhist history, the defeat of evil and the stages after death, so watching them is a form of teaching and earns merit; the unfurling of the giant thongdrel (thangka) at dawn brings blessings and is believed to liberate beings by sight.
Historical significance: many dances were introduced by Guru Rinpoche''s tradition, Terton Pema Lingpa and later masters, and the festivals were institutionalised under Zhabdrung and the Desis; they preserve centuries-old heritage, costumes and music.
Social significance: tshechus bring communities and families together, strengthening unity and identity; people wear their finest gho and kira and follow traditional etiquette; atsaras (clowns) entertain and convey social messages; and festivals support local economies and attract tourists, showcasing Bhutan''s living culture.', null, '[{"point": "Religious: held on 10th day in honour of Guru Rinpoche, mask dances (cham) teach Dharma, blessings, thongdrel, merit; Historical: introduced by Guru Rinpoche/ Pema Lingpa/ Zhabdrung traditions, preserve heritage", "marks": 6}, {"point": "Social: community gathering, unity and identity, family reunions, traditional dress and etiquette, atsaras humour, economy and tourism", "marks": 4}]'::jsonb, (select id from public.subjects where slug = 'bhutan-institutions-development'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'bhutan-institutions-development') and t.slug = 'media-and-culture'), (select id from public.exam_papers where code = 'me-general-3'), 'standard', 10,
    1080, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": [], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper III (General): BCSE 2022, batch 2", "source": {"title": "BCSE 2022 Main Examination, General category, Paper III", "year": 2022, "url": "https://rcsc.gov.bt/bcse-past-question-papers/"}}'::jsonb, 'me-general-3-2022b2-a3', 2, null, null, null, null)
