with nq as (
  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'analytical', 'Since 1961, Bhutan''s development has been progressive, with commendable economic performance and improvement in social indicators such as literacy, life expectancy and gender equality. As a result, Bhutan will be graduating from the category of Least Developed Country. Despite this progress, what are some of the pressing challenges that could derail Bhutan''s socio-economic development going forward? Suggest interventions to address these challenges. (20 marks)', 'Pressing challenges:
1. A narrow economy dependent on hydropower, tourism and imports, vulnerable to shocks.
2. High youth unemployment and a mismatch between education and the skills employers need.
3. Large-scale emigration of educated and skilled people (brain drain).
4. Fiscal deficits, rising public debt and pressure on foreign currency reserves.
5. Loss of concessional aid and trade preferences after LDC graduation.
6. Climate change and disasters - GLOFs, floods, landslides and erratic rainfall affecting agriculture and hydropower.
7. Rural-urban migration, fallow land and declining food self-sufficiency.
8. Rising non-communicable diseases and health costs.
9. Social problems such as substance abuse and weakening community vitality.
10. A small, weak private sector and difficulties in doing business.
Interventions:
1. Diversify the economy - tourism, agriculture and agro-processing, ICT and digital services, manufacturing and the Gelephu Mindfulness City - and strengthen the private sector through easier business regulations and access to finance.
2. Reform education and expand technical and vocational training aligned with market needs; support entrepreneurship and youth employment schemes.
3. Retain talent through better pay, career growth and opportunities, and encourage the return of Bhutanese abroad.
4. Maintain fiscal discipline, reform taxes (e.g. GST) and manage debt prudently; build reserves through exports and import substitution.
5. Implement a smooth LDC transition strategy with development partners.
6. Invest in climate adaptation and disaster preparedness.
7. Modernise agriculture to revive fallow land and improve food security.
8. Focus on preventive health and healthy lifestyles.
9. Strengthen families, communities and programmes for youth.', null, '[{"point": "Challenges: narrow economy and dependence on hydropower/ imports, youth unemployment, emigration/ brain drain, fiscal deficit and public debt, low FCR, climate change and disasters, rural-urban migration and fallow land, NCDs and health costs, quality of education and skills mismatch, inequality, small private sector, loss of LDC support, substance abuse", "marks": 10}, {"point": "Interventions: diversification and private sector growth, skills and education reform (TVET), job creation and entrepreneurship, retention policies, fiscal discipline and revenue reform, climate resilience, agriculture modernisation, health prevention, smooth LDC transition strategy, digital economy", "marks": 10}]'::jsonb, (select id from public.subjects where slug = 'bhutan-institutions-development'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'bhutan-institutions-development') and t.slug = 'development-challenges'), (select id from public.exam_papers where code = 'me-general-3'), 'standard', 20,
