  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'analytical', 'Youth unemployment has always been one of the pressing social issues in the country. According to the 2021 Labour Force Survey Report, the overall youth unemployment rate was 20.9% (6,492 persons), slightly down by 1.7 percentage points from 22.6% in 2020. What could be the possible reasons for the decrease in the unemployment rate? Suggest three to four strategic interventions to bring down youth unemployment in the country. (20 marks)', 'Possible reasons for the decrease:
1. Government COVID-19 response programmes created jobs and training - e.g. the Build Bhutan Project (construction jobs for Bhutanese), the Economic Contingency Plan, skilling programmes (De-suung Skilling Programme), the Youth Engagement and Livelihood Programme and support for agriculture.
2. Many youth moved into farming and other self-employment during the pandemic.
3. More young people went abroad for work or study, reducing the number of job seekers at home.
4. Some economic recovery in 2021.
5. Some youth may have stopped looking for work or gone back to studies (leaving the labour force), which also lowers the measured rate.
Strategic interventions:
1. Skills that match the market: expand technical and vocational training, apprenticeships and internships linked to industry needs, and reform education to build practical and digital skills.
2. Entrepreneurship: provide start-up finance (low-interest loans, grants), incubation centres, mentoring and easier business registration for young entrepreneurs.
3. Private sector growth: improve the business environment and attract FDI, and develop new sectors such as ICT, tourism, agro-processing and the Gelephu Mindfulness City to create jobs.
4. Changing attitudes and job matching: career guidance in schools, labour market information, promoting the dignity of blue-collar work, and well-regulated overseas employment programmes.', null, '[{"point": "Reasons for decrease: COVID-era government programmes (Build Bhutan Project, Skills Development Plan, Youth Engagement and Livelihood Programme, De-suung skilling), youth returning to farming/ agriculture, emigration/ further studies abroad, economic recovery, temporary jobs, discouraged job seekers leaving labour force, survey/ definition effects", "marks": 8}, {"point": "Three to four interventions explained: TVET and skills aligned with market, entrepreneurship and start-up financing, private sector growth and FDI, career guidance and job matching, attitude change towards blue-collar jobs, overseas employment programmes, agriculture commercialisation, apprenticeships/ internships", "marks": 12}]'::jsonb, (select id from public.subjects where slug = 'bhutan-institutions-development'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'bhutan-institutions-development') and t.slug = 'employment-and-youth'), (select id from public.exam_papers where code = 'me-general-3'), 'standard', 20,
    2160, 'historical_official', 'awaiting_review',
